examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    MonarchTextField({{fieldLabel}}, text: $name)
    HStack(spacing: theme.spacing.space2) {
        MonarchButton({{save}}, variant: .primary) {}
        MonarchButton({{leave}}) { isAsking = true }
    }
    Text("Current page: " + page)
}
.padding()
.monarchUnsavedChangesGuard(
    isPresented: $isAsking,
    hasChanges: true,
    labels: MonarchUnsavedChangesGuardLabels(
        title: {{dialog.title}},
        message: {{dialog.message}},
        keepEditing: {{dialog.keepEditing}},
        discard: {{dialog.discard}},
        save: {{dialog.save}}
    ),
    onSave: { try await Task.sleep(for: .milliseconds(600)) },
    onLeave: { _ in page = {{leftPage}} }
)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var name = {{name}}
@State private var page = {{page}}
@State private var isAsking = false

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var name = "Weekly planning v2"
@State private var page = "Editor"
@State private var isAsking = false

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space3) {
    MonarchTextField("Board name", text: $name)
    HStack(spacing: theme.spacing.space2) {
        MonarchButton("Save", variant: .primary) {}
        MonarchButton("Go to overview") { isAsking = true }
    }
    Text("Current page: " + page)
}
.padding()
.monarchUnsavedChangesGuard(
    isPresented: $isAsking,
    hasChanges: true,
    labels: MonarchUnsavedChangesGuardLabels(
        title: "Discard unsaved changes?",
        message: "Your changes have not been saved. If you leave now, they will be lost.",
        keepEditing: "Keep editing",
        discard: "Discard changes",
        save: "Save and leave"
    ),
    onSave: { try await Task.sleep(for: .milliseconds(600)) },
    onLeave: { _ in page = "Overview" }
)

